	world.Parent = vp;
	local cam = Instance.new("Camera");
	cam.FieldOfView = 50;
	cam.Parent = vp;
	vp.CurrentCamera = cam;
	self.Preview.Viewport = vp;
	self.Preview.World = world;
	self.Preview.Camera = cam;
	vp.InputBegan:Connect(function(input)
		if (input.UserInputType == Enum.UserInputType.MouseButton1) then
			self.Preview.Dragging = true;
			self.Preview.LastMouse = Vector2.new(input.Position.X, input.Position.Y);
			input.Changed:Connect(function()
				if (input.UserInputState == Enum.UserInputState.End) then
					self.Preview.Dragging = false;
				end
			end);
		end
	end);
	self.Services.UserInputService.InputChanged:Connect(function(input)
		if (self.Preview.Dragging and (input.UserInputType == Enum.UserInputType.MouseMovement)) then
			local current = Vector2.new(input.Position.X, input.Position.Y);
			local delta = current - self.Preview.LastMouse;
			self.Preview.LastMouse = current;
			self.Preview.Yaw = self.Preview.Yaw - (delta.X * 0.015);
			self.Preview.Pitch = math.clamp(self.Preview.Pitch - (delta.Y * 0.015), -1.35, 1.35);
			self:UpdatePreviewCamera();
		end
	end);
	vp.InputChanged:Connect(function(input)
		if (input.UserInputType == Enum.UserInputType.MouseWheel) then
			self.Preview.ZoomOffset = math.clamp((self.Preview.ZoomOffset or 0) - (input.Position.Z * 0.6), -8, 12);
			self:UpdatePreviewCamera();
		end
	end);
	task.spawn(function()
		task.wait(0.2);
		self:CloneLocalPlayerModel();
	end);
	self.Services.RunService.RenderStepped:Connect(function(dt)
		if (self.State.IsOpen and self.State.SidePanelOpen) then
			if (not self.Preview.Dragging and self.Config.Toggles.PreviewRotate) then
				local spd = (self.Config.Values.PreviewRotateSpeed or 3) * 0.2;
				self.Preview.Yaw = (self.Preview.Yaw or 0) + (dt * spd);
				self:UpdatePreviewCamera();
			end
			self:SyncPreviewRig();
		end
	end);
end;
Hub.CloneLocalPlayerModel = function(self)
	if self.Preview.Model then
		pcall(function()
			self.Preview.Model:Destroy();
		end);
		self.Preview.Model = nil;
	end
	local lp = self.Services.Players.LocalPlayer;
	local char = lp.Character;
	if not char then
		return;
	end
	local clone = Instance.new("Model");
	clone.Name = LUAOBFUSACTOR_DECRYPT_STR_0("\198\172\1\20\82\89\225\140\13\5", "\60\150\222\100\98\59");
	local cframeOrigin = char:GetPivot();
	for _, item in ipairs(char:GetChildren()) do
		if (item:IsA(LUAOBFUSACTOR_DECRYPT_STR_0("\118\52\94\68\207", "\81\37\92\55\54\187\218")) or item:IsA("Pants") or item:IsA("ShirtGraphic") or item:IsA("BodyColors") or item:IsA(LUAOBFUSACTOR_DECRYPT_STR_0("\35\76\172\37\128\3\80\168\37\172\5\87\165", "\225\96\36\205\87"))) then
			pcall(function()
				local c = item:Clone();
				c.Parent = clone;
			end);
		end
	end
	local hum = char:FindFirstChildOfClass("Humanoid");
	if hum then
		pcall(function()
			local hClone = hum:Clone();
			hClone.DisplayDistanceType = Enum.HumanoidDisplayDistanceType.None;
			hClone.HealthDisplayType = Enum.HumanoidHealthDisplayType.AlwaysOff;
			hClone.Parent = clone;
		end);
	end
	local turnFront = CFrame.Angles(0, math.pi, 0);
	for _, item in ipairs(char:GetChildren()) do
		if item:IsA(LUAOBFUSACTOR_DECRYPT_STR_0("\203\167\81\124\76\78\27\253", "\105\137\198\34\25\28\47")) then
			local p = item:Clone();
			p.Anchored = true;
			p.CanCollide = false;
			p.CanTouch = false;
			p.CanQuery = false;
			p.CastShadow = false;
			local rel = cframeOrigin:ToObjectSpace(item.CFrame);
			p.CFrame = turnFront * rel;
			p.Parent = clone;
		elseif item:IsA("Accessory") then
			local acc = item:Clone();
			local h = acc:FindFirstChild("Handle");
			if (h and h:IsA(LUAOBFUSACTOR_DECRYPT_STR_0("\51\168\82\115\240\16\187\85", "\160\113\201\33\22"))) then
				h.Anchored = true;
				h.CanCollide = false;
				local rel = cframeOrigin:ToObjectSpace(h.CFrame);
				h.CFrame = turnFront * rel;
			end
			acc.Parent = clone;
		end
	end
	clone.Parent = self.Preview.World;
	self.Preview.Model = clone;
	self.Preview.ZoomOffset = 0;
	self:UpdatePreviewCamera();
	self:TogglePreviewAura(true);
	self:UpdatePreviewLocalESP();
end;
Hub.SyncPreviewRig = function(self)
	if not (self.Preview.Model and self.Preview.Model.Parent) then
		return;
	end
	local lp = self.Services.Players.LocalPlayer;
	local char = lp and lp.Character;
	if not (char and char.Parent) then
		return;
	end
	local cframeOrigin = char:GetPivot();
	local turnFront = CFrame.Angles(0, math.pi, 0);
	for _, part in ipairs(self.Preview.Model:GetChildren()) do
		if part:IsA("BasePart") then
			local livePart = char:FindFirstChild(part.Name);
			if (livePart and livePart:IsA("BasePart")) then
				local rel = cframeOrigin:ToObjectSpace(livePart.CFrame);
				part.CFrame = turnFront * rel;
			end
		elseif part:IsA("Accessory") then
			local h = part:FindFirstChild("Handle");
			local liveAcc = char:FindFirstChild(part.Name);
			local liveH = liveAcc and liveAcc:FindFirstChild("Handle");
			if (h and liveH and liveH:IsA(LUAOBFUSACTOR_DECRYPT_STR_0("\246\89\191\162\153\172\198\76", "\205\180\56\204\199\201"))) then
				local rel = cframeOrigin:ToObjectSpace(liveH.CFrame);
				h.CFrame = turnFront * rel;
			end
		end
	end
	for _, child in ipairs(self.Preview.Model:GetChildren()) do
		if (child:IsA("Tool") or (child:IsA(LUAOBFUSACTOR_DECRYPT_STR_0("\174\209\56\29\143", "\120\227\190\92")) and (child.Name ~= "PreviewRig"))) then
			pcall(function()
				child:Destroy();
			end);
		end
	end
end;
Hub.GetPreviewFraming = function(self)
	local defaultDist = 6.8;
	local defaultCenterY = 0;
	if not self.Preview.Model then
		return defaultDist, defaultCenterY;
	end
	local bboxCf, bboxSize = nil, nil;
	pcall(function()
		bboxCf, bboxSize = self.Preview.Model:GetBoundingBox();
	end);
	if (not bboxSize or (bboxSize.Y < 0.5)) then
		return defaultDist, defaultCenterY;
	end
	local fov = (self.Preview.Camera and self.Preview.Camera.FieldOfView) or 50;
	local fovRad = math.rad(fov);
	local halfTan = math.tan(fovRad / 2);
	local vp = self.Preview.Viewport;
	local vpSize = (vp and vp.AbsoluteSize) or Vector2.new(220, 260);
	local aspect = ((vpSize.X > 0) and (vpSize.Y > 0) and (vpSize.X / vpSize.Y)) or 0.85;
	local distY = (bboxSize.Y / 2) / halfTan;
	local maxHorizontal = math.max(bboxSize.X, bboxSize.Z);
	local distX = (maxHorizontal / 2) / (halfTan * aspect);
	local idealDist = math.max(distY, distX) * 1.25;
	local clampedDist = math.clamp(idealDist, 2.5, 25);
	local centerY = bboxCf.Position.Y;
	return clampedDist, centerY;
end;
Hub.UpdatePreviewCamera = function(self)
	if not self.Preview.Camera then
		return;
	end
	local autoDist, centerY = self:GetPreviewFraming();
	local manualZoom = self.Preview.ZoomOffset or 0;
	local dist = math.clamp(autoDist + manualZoom, 2, 30);
	local target = Vector3.new(0, centerY, 0);
	local cf = CFrame.new(target) * CFrame.Angles(0, self.Preview.Yaw or 0, 0) * CFrame.Angles(self.Preview.Pitch or 0, 0, 0) * CFrame.new(0, 0, dist);
	self.Preview.Camera.CFrame = CFrame.lookAt(cf.Position, target);
end;
Hub.TogglePreviewAura = function(self, state)
	self.Config.Toggles.PreviewAura = state;
	if not self.Preview.Model then
		return;
	end
	local root = self:GetRoot(self.Preview.Model) or self.Preview.Model:FindFirstChildWhichIsA("BasePart");
	if not root then
		return;
	end
	if state then
		if not self.Preview.AuraEmitter then
			local p = Instance.new("ParticleEmitter");
			p.Name = "PreviewAuraEmitter";
			p.Texture = LUAOBFUSACTOR_DECRYPT_STR_0("\47\94\7\122\48\79\220\246\52\88\69\52\108\14\141\177\109\5\71\43\122\4", "\130\93\60\127\27\67\60\185");
			p.Rate = 24;
			p.Lifetime = NumberRange.new(0.8, 1.4);
			p.Speed = NumberRange.new(1.5, 3);
			p.Size = NumberSequence.new({NumberSequenceKeypoint.new(0, 0.4),NumberSequenceKeypoint.new(1, 1.2)});
			p.Transparency = NumberSequence.new({NumberSequenceKeypoint.new(0, 0.2),NumberSequenceKeypoint.new(1, 1)});
			p.Color = ColorSequence.new(Color3.fromRGB(255, 255, 255));
			p.LightEmission = 0.8;
			p.Parent = root;
			self.Preview.AuraEmitter = p;
		end
	elseif self.Preview.AuraEmitter then
		pcall(function()
