					local lRole = Instance.new("TextLabel");
					lRole.Name = LUAOBFUSACTOR_DECRYPT_STR_0("\26\13\126\206\134\65\42\7\126", "\32\72\98\18\171\202");
					lRole.Size = UDim2.new(1, 0, 0, 16);
