Hub.IsCoinBagFull = function(self)
	local isFull = false;
	local limit = self.Config.Values.AutoFarmBagLimit or 50;
	pcall(function()
		local lp = self.Services.Players.LocalPlayer;
		local pgui = lp:FindFirstChild(LUAOBFUSACTOR_DECRYPT_STR_0("\224\200\195\12\213\214\229\0\217", "\117\176\164\162"));
		local mg = pgui and pgui:FindFirstChild("MainGUI");
		if not mg then
			return;
		end
		local coinBags = mg:FindFirstChild("Game") and mg.Game:FindFirstChild("CoinBags");
		if not coinBags then
			return;
		end
		local container = coinBags:FindFirstChild("Container");
		if container then
			for _, bagFrame in ipairs(container:GetChildren()) do
				if (bagFrame:IsA("Frame") and bagFrame.Visible) then
					local fullLabel = bagFrame:FindFirstChild("Full");
					if (fullLabel and fullLabel.Visible) then
						isFull = true;
						return;
					end
					for _, lbl in ipairs(bagFrame:GetDescendants()) do
						if (lbl:IsA(LUAOBFUSACTOR_DECRYPT_STR_0("\176\199\29\228\246\120\134\199\9", "\25\228\162\101\144\186")) and lbl.Visible) then
							local txt = lbl.Text:match("(%d+)");
							if txt then
								local num = tonumber(txt);
								if (num and (num >= limit)) then
									isFull = true;
									return;
								end
							end
						end
					end
				end
			end
		end
		local scriptFolder = coinBags:FindFirstChild(LUAOBFUSACTOR_DECRYPT_STR_0("\107\57\176\0\208\229\79\21\182\0\230\229\65\56\188\28\193\231\90\63\169\26", "\132\40\86\217\110\146"));
		local fullNotif = scriptFolder and scriptFolder:FindFirstChild("FullBagNotification");
		if (fullNotif and fullNotif.Visible) then
			isFull = true;
			return;
		end
	end);
	return isFull;
end;
Hub.GetAvailableCoins = function(self)
	local list = {};
	local cs = self.Services.CollectionService;
	local ok, tagged = pcall(function()
		return cs:GetTagged("CoinVisual");
	end);
	if (ok and (type(tagged) == "table") and (#tagged > 0)) then
		for _, v in ipairs(tagged) do
			if (v and v.Parent and v:IsA(LUAOBFUSACTOR_DECRYPT_STR_0("\92\202\52\185\151\114\238\74", "\62\30\171\71\220\199\19\156"))) then
				if (not v:GetAttribute("Collected") and not v:GetAttribute(LUAOBFUSACTOR_DECRYPT_STR_0("\100\64\160\51\73\204", "\45\32\37\204\86\61\169\79"))) then
					table.insert(list, v);
				end
			end
		end
	end
	if (#list == 0) then
		local coinContainer = self.Services.Workspace:FindFirstChild("CoinContainer", true);
		if coinContainer then
			for _, c in ipairs(coinContainer:GetChildren()) do
				if (c:IsA("BasePart") and c.Parent and not c:GetAttribute("Collected")) then
					table.insert(list, c);
				elseif (c:IsA("Model") and c.Parent) then
					local p = c.PrimaryPart or c:FindFirstChildWhichIsA("BasePart");
					if (p and not p:GetAttribute("Collected")) then
						table.insert(list, p);
					end
				end
			end
		end
	end
	return list;
end;
Hub.GetTouchTargets = function(self, coin)
	local list = {};
	local seen = {};
	local function add(p)
		if (p and not seen[p] and p:IsA(LUAOBFUSACTOR_DECRYPT_STR_0("\119\84\22\185\133\125\71\65", "\28\53\53\101\220\213")) and p:FindFirstChildOfClass("TouchTransmitter")) then
			seen[p] = true;
			table.insert(list, p);
		end
	end
	add(coin);
	if coin then
		for _, v in ipairs(coin:GetChildren()) do
			add(v);
		end
		local par = coin.Parent;
		if par then
			if par:IsA("BasePart") then
				add(par);
			end
			for _, v in ipairs(par:GetChildren()) do
				add(v);
			end
		end
	end
	if ((#list == 0) and coin) then
		table.insert(list, coin);
	end
	return list;
end;
Hub.FireCoinTouch = function(self, coin)
	if (type(firetouchinterest) ~= "function") then
		return;
	end
	if (not coin or not coin.Parent) then
		return;
	end
	local now = os.clock();
	if ((now - (self.AutoFarm.LastTouch or 0)) < 0.05) then
		return;
	end
	self.AutoFarm.LastTouch = now;
	local lp = self.Services.Players.LocalPlayer;
	local char = lp and lp.Character;
	local root = char and self:GetRoot(char);
	if not root then
		return;
	end
	for _, p in ipairs(self:GetTouchTargets(coin)) do
		pcall(firetouchinterest, root, p, 0);
		pcall(firetouchinterest, root, p, 1);
	end
end;
