	for _, plr in ipairs(self.Services.Players:GetPlayers()) do
		if ((plr ~= self.Services.Players.LocalPlayer) and plr.Character and plr.Character:FindFirstChild("Knife")) then
			return self:GetRoot(plr.Character);
